  'mingjiao': [JobSkill(name: '摧心掌', type: '攻击', cd: '—', desc: '单体近身攻击 增加外功攻击 —— 明教弟子的入门功夫。使用之后可以连续对目标造成伤害。', mind: 0), JobSkill(name: '血战八方', type: '攻击', cd: '—', desc: '范围攻击 自身周围5米范围内，最多10个目标，外功攻击增加', mind: 0), JobSkill(name: '葵花神力', type: '增益', cd: '—', desc: '单体强化 增加目标力量 —— 明教弟子给予朋友的关怀。使用之后可以提升友方目标的力量。', mind: 0), JobSkill(name: '炎龙无双', type: '攻击', cd: '—', desc: '单体近身攻击 火攻击增加 —— 明教绝技之一，是吕师襄圣使的得意功夫。使用之后可以对目标造成大量火属性伤害。', mind: 1), JobSkill(name: '葵花逐日', type: '攻击', cd: '—', desc: '提高自身移动速度50%，持续若干秒。 —— 葵花宝典中秘载的轻功。使用之后可以使你形如鬼魅，移动速度大幅度提高。', mind: 1), JobSkill(name: '葵花点穴手', type: '攻击', cd: '—', desc: '单体近身攻击 将目标封穴，持续数秒，封穴状态下无法进行任何操作', mind: 1), JobSkill(name: '葵花向阳', type: '增益', cd: '—', desc: '群体强化 使自身周围的队友(包括自己)外功攻击增加', mind: 1), JobSkill(name: '怒发冲冠', type: '攻击', cd: '—', desc: '消耗气若干点。瞬间释放狂暴状态，增加自身外功攻击若干点，同时降低一定外功防御，持续300秒。', mind: 2), JobSkill(name: '李代桃僵', type: '状态', cd: '—', desc: '状态 为目标绑上复活标记，死后可以选择复活，复活后恢复部分血气', mind: 2), JobSkill(name: '斗转星移', type: '攻击', cd: '—', desc: '单体近身攻击 外功攻击增加，同时打消敌人怒气', mind: 2), JobSkill(name: '激流甲', type: '攻击', cd: '—', desc: '被动蕴含 防具的外功防御效果增加 —— 使你从防具中获得的外功防御力大幅提高。', mind: 3), JobSkill(name: '水淹七军', type: '攻击', cd: '—', desc: '单体近身攻击 冰攻击增加，有几率令目标进入虚弱状态，体力和定力降低', mind: 3), JobSkill(name: '水神下凡', type: '保命', cd: '—', desc: '防御状态，获得怒气的速度增加，此状态下攻击目标，一定几率使目标进入破绽状态，内外攻攻击降低', mind: 3), JobSkill(name: '长生水', type: '解控', cd: '—', desc: '单体净化 解除自己身上持续减血的效果 —— 以长生之水洗净你的身心。使用之后可以解除你受到的持续掉血效果。只有在水神下凡姿态下才能使用。', mind: 3), JobSkill(name: '烈焰刀', type: '攻击', cd: '—', desc: '被动蕴含 刀斧、枪棒类武器的基本外功攻击效果增加', mind: 4), JobSkill(name: '火烧赤壁', type: '攻击', cd: '—', desc: '单体近身攻击 火攻击增加，有几率使目标灼烧', mind: 4), JobSkill(name: '火神下凡', type: '状态', cd: '—', desc: '攻击状态 命中与会心攻击增加 —— 火神祝融从天而降，带着烈火的气息附身在你身上。使用之后使你摆出攻击型姿态。', mind: 4), JobSkill(name: '地狱火', type: '攻击', cd: '—', desc: '群体攻击 令自身周围5米范围内，最多4个目标昏睡，持续数秒，昏睡状态下无法进行任何操作，一旦受到伤害便会打断该状态', mind: 4), JobSkill(name: '火焰连环斩', type: '攻击', cd: '—', desc: '单体近身攻击 对目标造成额外直接伤害 —— 明教绝技之一，是庞万春圣使的得意功夫。使用之后可以对目标发动毁天灭地的一击。', mind: 5), JobSkill(name: '坐地求全', type: '解控', cd: '—', desc: '解除自己的散功状态，并免疫散功，不能解除心法等级比自己高的玩家施加的散功状态。', mind: 5), JobSkill(name: '无中生有', type: '攻击', cd: '—', desc: '状态 攻击无视对方所有防御 —— 山中老人霍山遗留的神功，人挡杀人，佛挡杀佛。使用之后可以使你的攻击忽略目标防御力。', mind: 5), JobSkill(name: '烽火连城', type: '攻击', cd: '—', desc: '群体攻击 使自身周围5米范围内，最多6个目标进入灼烧状态，持续受到火属性伤害。', mind: 6), JobSkill(name: '纯阳无极', type: '攻击', cd: '—', desc: '使用后增加自身的火攻击和火抗性 —— 天下武学至宝九阳天书中所载的神功。使用之后可以提升你的火属性伤害和抗火能力。', mind: 6), JobSkill(name: '怒火连斩', type: '攻击', cd: '—', desc: '瞬发技能，给自身加一个状态持续一定时间，在状态持续的时间内击中目标将会100%获得一个持续10秒的移动加速状态，增加自身移动速度50%，并且在接下来的15次攻击中每次伤害提高。次数结束后，即使状态没有消失，也不会有伤害加成的效果。如果攻击未击中,仍然计算攻击次数。', mind: 6)],
  'gaibang': [JobSkill(name: '蟠龙击', type: '攻击', cd: '—', desc: '单体近身攻击 增加外功攻击，击中获得1个连击点', mind: 0), JobSkill(name: '千里横行', type: '攻击', cd: '—', desc: '范围攻击 自身周围8米范围内，最多15个目标，外功攻击增加', mind: 0), JobSkill(name: '如影随形', type: '增益', cd: '—', desc: '单体强化 增加目标身法 —— 丐帮弟子给予朋友的关怀，使用之后可以提升友方目标的身法。', mind: 0), JobSkill(name: '冲阵斩将', type: '攻击', cd: '—', desc: '单体近身攻击 毒攻击增加 —— 丐帮绝技之一，是奚三祁长老的得意功夫。使用之后可以对目标造成大量毒属性伤害。', mind: 1), JobSkill(name: '八步赶蟾', type: '攻击', cd: '—', desc: '状态 提高自身移动速度 —— 武林中极为经典的地堂轻功。使用之后传说可以八步之内追上月中金蟾。', mind: 1), JobSkill(name: '雪泥鸿爪', type: '攻击', cd: '—', desc: '单体近身技能 使目标散功，持续数秒，散功状态下可以移动，但无法使用技能', mind: 1), JobSkill(name: '粘衣十八跌', type: '增益', cd: '—', desc: '群体强化 自身周围7米，有效人数12，队友(包括自己)闪避增加', mind: 1), JobSkill(name: '飞龙在天', type: '攻击', cd: '—', desc: '单体攻击 直接对目标造成额外直接伤害 —— 降龙十八掌第二掌，双掌连环，令敌人避无可避。使用之后可以对目标造成大量伤害。', mind: 2), JobSkill(name: '潜龙勿用', type: '攻击', cd: '—', desc: '群体攻击 令自身周围5米范围内，最多4个目标失明，持续数秒，失明状态下无法进行任何操作，会在一定区域内随机移动', mind: 2), JobSkill(name: '见龙在田', type: '攻击', cd: '—', desc: '上毒状态 该状态下攻击能使目标中毒，持续伤血', mind: 2), JobSkill(name: '将军令', type: '攻击', cd: '—', desc: '防具的外功防御效果增加 —— 使你从防具中获得的外功防御力大幅提高。', mind: 3), JobSkill(name: '青龙出水', type: '攻击', cd: '—', desc: '单体近身攻击 外功攻击增加，击中目标有几率恢复一定量血', mind: 3), JobSkill(name: '擒龙式', type: '保命', cd: '—', desc: '防御状态 获得怒气的速度增加，此状态下攻击目标，有几率使目标进入僵硬状态，命中降低', mind: 3), JobSkill(name: '沛然有雨', type: '解控', cd: '—', desc: '单体净化 解除自己身上的虚弱状态 —— 清风徐来，沛然有雨。使用之后可以解除你受到的虚弱效果。只有在擒龙式姿态下才能使用。', mind: 3), JobSkill(name: '破虏令', type: '攻击', cd: '—', desc: '被动蕴含 刀斧、枪棒类武器的基本外功攻击效果增加', mind: 4), JobSkill(name: '震惊百里', type: '攻击', cd: '—', desc: '单体近身攻击 外功攻击增加，击中目标直接获得一个连击段', mind: 4), JobSkill(name: '控鹤式', type: '状态', cd: '—', desc: '攻击状态 获得三段连击的能力，该状态下攻击目标，技能暴击有几率直接增加两个连击段', mind: 4), JobSkill(name: '履霜冰至', type: '攻击', cd: '—', desc: '使用之后下一次攻击的效果翻倍。 —— 山雨欲来，履霜冰至。使用之后可以使你下一次攻击的效果翻倍', mind: 4), JobSkill(name: '亢龙有悔', type: '攻击', cd: '—', desc: '单体近身攻击 对目标直接造成额外直接伤害', mind: 5), JobSkill(name: '神龙摆尾', type: '解控', cd: '—', desc: '解除自己的定身、昏睡状态，并免疫定身、昏睡，不能解除心法等级比自己高的玩家施加的定身、昏睡状态。', mind: 5), JobSkill(name: '龙战于野', type: '攻击', cd: '—', desc: '消耗所有怒气。瞬间释放。状态：短时间内自身闪避暴增若干点，持续15秒。需要满怒状态。', mind: 5), JobSkill(name: '棒打狗头', type: '攻击', cd: '—', desc: '单体远程攻击 外功攻击增加，将目标封穴，同时降低移动速度，持续数秒。', mind: 6), JobSkill(name: '天下无狗', type: '攻击', cd: '—', desc: '使用之后，对自身范围多个目标造成直接伤害、同时附加僵硬效果。', mind: 6), JobSkill(name: '横扫乾坤', type: '攻击', cd: '—', desc: '范围攻击，在15秒内持续对自身周围半径5米范围内最多6个目标造成伤害并增加毒攻击数点，并造成目标减速，同时自身免疫控制技能，不能攻击不能使用战斗技能，需要装备武器。', mind: 6)],
